from save_review import save
save(1151,{4:'Death Guard Marine (pre-Heresy) wielding Manreaper 一名荷鲁斯之乱前的死亡守卫战士，手持收割者动力镰刀。',6:'莫塔里安、纳垢传令官泰弗斯，以及其他死亡守卫星际战士都曾使用收割者。据载，泰弗斯的收割者曾浸泡在纳垢王座渗出的污秽之中。',11:'泪滴——卡拉斯·提丰的武器。',13:'Manreaper of Typhus, Herald of Nurgle 纳垢传令官泰弗斯的收割者'},notes={4:'pre-Heresy 指荷鲁斯之乱发生前，不是叛乱早期。',6:'Typhus依官方泰弗斯，旧名Calas Typhon依核心卡拉斯·提丰，保留改名前后区别。',11:'Lakrimae是镰刀名，区别舰船Lachrymae泪痕号；不因字形接近合并。'},terms=[('Lakrimae','泪滴（动力镰刀）'),('Power Scythe','动力镰刀')])
save(1152,{2:'动力长枪，又称动力长矛，是在长杆末端装有动力刃的特殊动力武器。刃部周围产生破坏性能量场，使它与大多数动力武器一样，能够轻易撕开各种材料。',5:'白疤战团的星际战士尤其偏爱动力长枪。战团科技战士针对战斗兄弟的作战风格制造这种武器：它的原理与其他动力武器相仿，但攻击范围更长。骑乘摩托的白疤能单手持枪，在冲锋中重创敌军。不过，长距离优势也带来代价；一旦敌人贴身，长枪就显得笨重难使。',9:'帝国骑士步行机甲也使用更大型的动力长枪，尤其是骑士枪骑兵。',11:'Falling-Star Pattern Power Spear 流星型动力长矛',25:'毁灭之刃——简恩·扎尔使用。',29:'沃坎之矛——伏尔甘·赫斯坦使用。'},notes={5:'长枪并非不适合所有近战，而是在贴身缠斗时不够灵活；原文reach与hand-to-hand对照据此处理。',29:'武器以原体Vulkan命名，依核心为沃坎之矛；持有者Vulkan He’stan全名按官方为伏尔甘·赫斯坦，不能机械把两个Vulkan都改成同一人。'},terms=[('Power Lance','动力长枪'),('Power Spear','动力长矛'),('Falling-Star Pattern Power Spear','流星型动力长矛'),('Kontos Power Lance','骑矛动力长枪'),('Interceptor Lance','拦截者长枪'),('Star Glaive','星辰长刀'),('Banshee\'s Keen','女妖之嚎'),('Zhai Morenn','毁灭之刃')])
save(1153,{2:'动力槌是帝国的一类动力武器，最常由法务部使用，阿斯塔特等其他武装力量也会配备。',7:'动力槌本质上是一根包覆动力场的棍棒，但它的精妙之处在于力场强度可以大幅调节：既能在墙壁上砸出破洞，也能突然将一个人击昏。这种灵活性使它成为帝国执法力量的重要工具。法务部突击部队常将动力槌与镇压盾搭配，用于驱散暴动人群。',9:'动力槌有多种型号，结构差异也会影响使用方式。例如，经典的极限型短而沉重，几乎没有装饰，适合短促劈砸。即使不开启动力场，它也能像警棍一样有效打击，轻易敲断袭击者的骨头。海德拉弗型则更长、更轻、更纤细，带尖刺的护手不便反握。由于缺少其他型号的重量，它对技巧要求更高：使用者往往像击剑一样，以尖端轻刺对手，再让动力场完成杀伤。',13:'震撼槌是一种相似武器，但它以放电而非动力场使敌人丧失行动能力。',24:'考斯韦恩的失落之槌——暗黑天使。'},notes={7:'knock-out 是击昏而非仅推倒；shock troops 在此为执法突击力量，不表示另一个叫震慑的组织。',9:'choppy strokes 为短促劈砸，原“连贯敲击”不准确；reverse-grip即反握。',24:'Mace是槌类武器，原失落之杖会与法杖或灵能杖混淆，暂改失落之槌。'},terms=[('Power Maul','动力槌'),('Shock Maul','震撼槌'),('Worldbreaker','破世者'),('Illuminarum','启明之光'),('Weight of Duty','职责之重'),('Lost Mace of Corswain','考斯韦恩的失落之槌')])
save(1154,{2:'雷霆锤是一种设计古老的武器，使用与动力剑、动力拳相似的动力场。星际战士和恶魔猎手都会配备，主要使用者是突击终结者小队，以及有权从相应军械库领取装备的人物。',7:'多数动力武器持续释放能量场，雷霆锤则只在命中瞬间激活动力场，将能量保留至真正需要时，再集中释放毁灭性一击。撞击时，蓝色能量场伴着雷鸣般的巨响爆发，往往能击穿装甲，留下冒烟的破洞，蓝色电火花劈啪作响。它释放的力量足以掀翻未穿终结者甲的战士。与大多数其他近战武器相比，雷霆锤的主要缺点在于挥击缓慢。',11:'雷霆锤常与风暴盾搭配，为使用者提供强悍的近战杀伤力与防护。据旧记录，雷霆锤还能在一次攻击中释放全部巨大能量，使武器自毁，同时杀死使用者及周围敌人。但如今的雷霆锤似乎已移除这一功能，或者这种用法不再被视为合适的战术。',14:'重型雷霆锤是更庞大的雷霆锤型号，具有两个锤头，每个都包覆强大的破坏力场。它威力惊人，足以将刽子手生物的躯干砸成两段。',21:'沃坎使用过多种强大的雷霆锤，包括雷霆之首、黎明使者、燃烧之手和末日震颤。',23:'多恩之拳是一把巨型雷霆锤，由帝国之拳历任第一连连长传承；现由达纳斯·莱山德持有。',25:'破敌锤内置传送装置，使其主人、太空野狼的阿贾克·石拳能够投出战锤后，再将它传送回手中。',27:'夜曲之锤由火蜥蜴连长阿德拉克斯·阿伽顿使用。'},notes={7:'thunderous crack 为雷鸣般的响声，不是雷电形状的裂纹。原句未明确被震倒者一定是持锤者或目标，译文不擅作限定。',14:'Carnifex在此是泰伦刽子手生物，按GW09/GW10已核复数单位名处理，区别药剂师同名医疗器具。',21:'统一708等篇既定战锤名称；原雷暴云砧和毁灭震颤保留于原译对照。'},terms=[('Thunder Hammer','雷霆锤'),('Heavy Thunder Hammer','重型雷霆锤'),('Fist of Dorn','多恩之拳'),('Maekr','迈凯尔'),('Hammer of Baal','巴尔之锤'),('Veikskell','维克斯凯尔')])
save(1155,{4:'这柄教士权杖曾随主人经历十二次血腥远征。其独特的情绪感应动力回路，吸纳了历代持有它的教士所积蓄的怒火。'},title='狂怒祝福 Benediction of Fury',notes={4:'Borne是被携带、经历征战，不是born诞生；dozen依英文为十二。empathokinetic circuitry 暂按情绪感应动力回路理解。'},terms=[('Benediction of Fury','狂怒祝福'),('Empathokinetic Circuitry','情绪感应动力回路')])
save(1156,{2:'帝皇的闪电爪至今没有专属名称。大远征与荷鲁斯之乱时期的描绘中，它通常戴在帝皇左手；不同图像所画出的爪刃数量不一，从三根到五根都有。',6:'这件武器最终下落不明；后世描绘帝皇的图像中，不再出现这副闪电爪。'},notes={2:'digits 指手指状爪刃的数量，不是图像描述的种数；Emperor’s Lightning Claw为描述性名称，并非原文确认的武器真名。',6:'contemporary art 指底稿所说当代的帝皇图像，不据此断言现实此后所有官方新画作均未描绘该武器。'},terms=[('Emperor\'s Lightning Claw','帝皇闪电爪')])
save(1157,{2:'机械之死是一柄精工动力斧，铸造于神圣火星深处的地下秘库。它曾由星际战士战团的铸造大师使用，不仅能劈开战争机械与载具的金属装甲，还能斩伤其中的机魂。哪怕只被斧刃擦中，敌方坦克或步行机甲也可能内部尽毁。'},notes={2:'master-crafted为精工制作，不是使用者的等级；glancing blow为擦击，而非主动减轻力道的轻击。'},terms=[('Mortis Machina','机械之死')])
